// 366 scripture verses on hope, encouragement, comfort, joy, peace, and strength —
// one for every day of the year, including a leap day, with no repeats.
//
// Each entry carries the same reference in five public-domain translations:
// the King James Version (KJV, 1611/1769), the World English Bible (WEB,
// modern plain English), the American Standard Version (ASV, 1901, a close
// formal revision of the KJV), Young's Literal Translation (YLT, 1862/1898,
// deliberately literal/quirky), and the Bible in Basic English (BBE, 1949,
// short sentences and a restricted ~1000-word vocabulary — the easiest
// reading level of the five). Picked over NLT/MSG/TPT/TLB, which are
// commercially copyrighted (Tyndale, NavPress, Broadstreet) and can't be
// reproduced here without a license. Settings let a user either alternate
// between the versions day to day, or pin a single favorite version for
// every verse.
//
// Text is compiled from training knowledge in an offline environment with
// no live Bible-database access to verify against (attempted and blocked
// by this environment's network policy) — treat this as a good-faith first
// draft, not a certified-accurate transcription. The BBE entries in
// particular are a good-faith simple-English rendering in BBE's style
// rather than a verified transcription of the historical 1949 text. A
// handful of verses have genuine textual variants between translations
// (e.g. Job 13:15, where ASV and WEB follow a different Hebrew reading than
// KJV) — those are deliberate, not errors. Two pre-existing errors in the
// original KJV-only version of this file were caught and corrected in an
// earlier pass: Proverbs 12:25 had non-KJV wording, and the entry labeled
// "2 John 1:6" actually contained 1 Peter 1:8's text (fixed to the real,
// and correctly attributed, 2 John 1:3). Spot-check before relying on this
// beyond personal devotional use.
//
// A 6th translation, Reina-Valera Antigua (RVA, 1909, Spanish), was added
// later, picked over the 1960 Reina-Valera (RV60) specifically for its
// age-based public-domain status; RV60 is still copyrighted by the United
// Bible Societies.
//
// A 7th translation, ALM1911 (Portuguese), follows the same logic: it's
// João Ferreira de Almeida's translation in its 1911 revision, chosen for
// age-based public-domain status. Modern Almeida editions are NOT public
// domain -- "Almeida Revista e Corrigida" (ARC) and "Almeida Revista e
// Atualizada" (ARA) are both actively copyrighted by Sociedade Bíblica do
// Brasil (SBB, founded 1948, decades after this 1911 text), and "Almeida
// Corrigida Fiel" (ACF) is copyrighted by Sociedade Bíblica Trinitariana
// do Brasil. The 1911 revision predates SBB's existence and all of its
// later copyrighted re-editions, and both Almeida (d. 1691) and the 1911
// revisers are long deceased, putting it well past any reasonable
// copyright term -- the same reasoning as RVA above, just for Portuguese.
// Its archaic orthography (e.g. "creou" for "criou", "n'elle" for "nele")
// is original to the 1911 source text, not a transcription error. Sourced
// in bulk from a structured JSON dump (github.com/damarals/biblias, file
// ALM1911.json, itself explicitly marked public domain in that project's
// own translation table) rather than typed from memory.
//
// An 8th translation, Louis Segond 1910 (LSG, French), follows the same
// age-based public-domain logic: Louis Segond (d. 1885) produced the base
// translation, and the 1910 committee revision published after his death
// is long past any copyright term. LSG is the French-language counterpart
// to the KJV in both public-domain status and widespread recognition.
// Picked over the "Nouvelle Edition de Genève" (NEG), a later revision
// that IS actively copyrighted by the Société Biblique de Genève. Sourced
// in bulk from a structured JSON dump (github.com/juliend2/data-bible,
// file db/seed_data/louis-segond-formatted.json, whose own metadata marks
// it "Copyright": "Domaine public") rather than typed from memory. Some
// LSG Psalm entries (e.g. Psalm 23:1, 13:1) include the psalm's musical/
// authorship superscription (e.g. "Cantique de David.") as part of verse
// 1's text -- a genuine convention of how this source transcribes the
// historical Segond 1910 text, not a transcription error, so those French
// entries run slightly longer than their English/Spanish/Portuguese
// counterparts for the same ref.
//
// Unlike the English texts above (compiled from training-knowledge recall
// with no live verification), RVA, ALM1911, and LSG were sourced from
// live, structured bulk Bible text dumps and matched by reference
// programmatically.

